L19_1 = "\236\160\132 \235\182\128\235\140\128\236\155\144! \236\160\132\236\151\173\237\149\156 \235\146\164\236\151\144\235\143\132 \234\181\176\236\157\184 \236\160\149\236\139\160\236\157\132 \236\139\164\236\178\156\237\149\152\236\151\172 \236\130\172\235\158\140\235\147\164\236\157\132 \236\167\128\237\130\168 \236\155\140\236\187\164 \236\131\129\236\130\172\235\165\188 \237\150\165\237\149\180."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "\229\133\168\233\131\168\233\154\138\229\147\161\239\188\129\227\128\128\233\153\164\233\154\138\229\190\140\227\130\130\232\187\141\228\186\186\227\129\174\231\178\190\231\165\158\227\130\146\232\178\171\227\129\141\227\128\129\228\186\186\227\128\133\227\130\146\229\174\136\227\129\163\227\129\159\227\130\166\227\130\169\227\131\188\227\130\171\227\131\188\230\155\185\233\149\183\227\129\171\229\175\190\227\129\151\227\128\129"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Attention, all troops! Today we honor Master Sergeant Walker, who laid down his life so that others may live, even long after his active duty service."
L18_1.m_Talk_ENG = L19_1
