L18_1.m_Talk_TWN = L19_1
L19_1 = "\224\184\159\224\184\177\224\184\135\224\184\151\224\184\178\224\184\135\224\184\153\224\184\181\224\185\137 \224\184\129\224\184\173\224\184\135\224\184\151\224\184\171\224\184\178\224\184\163\224\184\151\224\184\177\224\185\137\224\184\135\224\184\171\224\184\161\224\184\148! \224\184\167\224\184\177\224\184\153\224\184\153\224\184\181\224\185\137\224\185\128\224\184\163\224\184\178\224\184\136\224\184\176\224\185\131\224\184\171\224\185\137\224\185\128\224\184\129\224\184\181\224\184\162\224\184\163\224\184\149\224\184\180\224\184\136\224\185\136\224\184\178\224\184\170\224\184\180\224\184\154\224\185\128\224\184\173\224\184\129\224\184\167\224\184\173\224\184\165\224\185\140\224\184\132\224\185\128\224\184\129\224\184\173\224\184\163\224\185\140 \224\184\156\224\184\185\224\185\137\224\184\170\224\184\165\224\184\176\224\184\138\224\184\181\224\184\167\224\184\180\224\184\149\224\184\130\224\184\173\224\184\135\224\184\149\224\184\153\224\185\128\224\184\158\224\184\183\224\185\136\224\184\173\224\185\131\224\184\171\224\185\137\224\184\132\224\184\153\224\184\173\224\184\183\224\185\136\224\184\153\224\185\132\224\184\148\224\185\137\224\184\173\224\184\162\224\184\185\224\185\136\224\184\149\224\185\136\224\184\173\224\185\132\224\184\155 \224\185\129\224\184\161\224\185\137\224\184\171\224\184\165\224\184\177\224\184\135\224\184\136\224\184\178\224\184\129\224\184\155\224\184\165\224\184\148\224\184\155\224\184\163\224\184\176\224\184\136\224\184\179\224\184\129\224\184\178\224\184\163\224\184\161\224\184\178\224\184\153\224\184\178\224\184\153\224\185\129\224\184\165\224\185\137\224\184\167"
L18_1.m_Talk_THA = L19_1
L19_1 = "Binh s\196\169, nghi\195\170m! H\195\180m nay, ch\195\186ng ta t\195\180n vinh Th\198\176\225\187\163ng S\196\169 Walker, ng\198\176\225\187\157i \196\145\195\163 hy sinh m\225\186\161ng s\225\187\145ng c\225\187\167a m\195\172nh \196\145\225\187\131 nh\225\187\175ng ng\198\176\225\187\157i kh\195\161c \196\145\198\176\225\187\163c s\225\187\145ng, th\225\186\173m ch\195\173 r\225\186\165t l\195\162u sau khi \195\180ng \225\186\165y \196\145\195\163 gi\225\186\163i ng\197\169."
L18_1.m_Talk_VTN = L19_1
L19_1 = "\229\133\168\228\189\147\233\152\159\229\145\152\239\188\129\229\144\145\233\128\128\228\188\141\229\144\142\228\187\141\232\183\181\232\161\140\231\157\128\229\134\155\228\186\186\231\178\190\231\165\158\228\191\157\230\138\164\229\184\130\230\176\145\228\187\172\231\154\132\230\178\131\229\133\139\228\184\138\229\163\171\239\188\140"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Achtung, alle Truppen! Heute ehren wir Master Sergeant Walker, der sein Leben gab, damit andere weiterleben k\195\182nnen, auch lange nach seinem aktiven Dienst."
L18_1.m_Talk_DEU = L19_1
